import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import type {IncomingMessage, OutgoingMessage} from '../types/messages.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

type Row = Omit<SessionSummary, 'createdAt' | 'updatedAt'> & {createdAt: string; updatedAt: string};
type Frame = {type: string; sessionId?: string; conversations?: Row[]; code?: string; message?: string};
const engines: ReturnType<typeof createHalEngine>[] = [];
const clients: WebSocket[] = [];
const logs: Array<{level: string; message: string; fields?: Record<string, unknown>}> = [];

class ObservedStore extends InMemorySessionStore {
  readonly requests: unknown[][] = [];
  override listFor(userId: string | number, options?: SessionListOptions): SessionSummary[] {
    this.requests.push([userId, options]);
    return super.listFor(userId, options);
  }
}

beforeEach(() => {
  logs.length = 0;
  const record = (level: string) => (_category: string, message: string, fields?: Record<string, unknown>) => {
    logs.push({level, message, fields});
  };
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const engine of engines.splice(0)) await engine.stop();
  setLogger();
});

async function start(
  session: SessionStore,
  history?: {enabled: boolean},
  resume = true,
  hooks?: NonNullable<HalEngineConfig['orchestrator']>['hooks']
) {
  // A variable preserves today's config assignability while exercising the additive option at runtime.
  const transport = {port: 0, resume: {enabled: resume}, history};
  const engine = createHalEngine({
    provider: {type: 'bedrock', region: 'eu-central-1', modelId: 'unused', maxTokens: 1},
    prompt: {identity: 'Conversation list acceptance'},
    auth: {ws: async () => ({id: 'owner'})},
    session,
    transport,
    orchestrator: {hooks},
  });
  engines.push(engine);
  await engine.start();
  const {port} = engine.server.address() as AddressInfo;
  return "'`ws://127.0.0.1:${port}/hal/ws`;
}

async function connect(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'credential-not-for-history']);
  clients.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await waitFor(() => frames.some(frame => frame.type === 'connected'));
  return {socket, frames};
}

async function waitFor(check: () => boolean) {
  const deadline = Date.now() + 1500;
  while ("'!check() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
  expect(check()).toBe(true);
}

async function request(peer: Awaited<ReturnType<typeof connect>>, payload: unknown) {
  const offset = peer.frames.length;
  peer.socket.send(JSON.stringify(payload));
  await waitFor(() => peer.frames.slice(offset).some(frame => ['"'conversation_list', 'error'].includes(frame.type)));
  peer.socket.send(JSON.stringify({type: 'ping', timestamp: 144}));
  await waitFor(() => peer.frames.slice(offset).some(frame => frame.type === 'pong'));
  return peer.frames.slice(offset).filter(frame => frame.type "'!== '"'pong');
}

function originalMembers(store: InMemorySessionStore): SessionStore {
  return {
    create: store.create.bind(store),
    get: store.get.bind(store),
    delete: store.delete.bind(store),
    count: store.count.bind(store),
    clear: store.clear.bind(store),
  };
}

// spec: specs/hal-engine-websocket-protocol/spec.md#conversation-list-validation
it('validates history frames and composite cursors without changing existing messages', () => {
  const before = {updatedAt: '2026-11-01T00:00:00.000Z', sessionId: 'last-row'};
  for (const frame of [
    {type: 'list_conversations'},
    {type: 'list_conversations', limit: 1},
    {type: 'list_conversations', limit: 200, before},
  ]) {
    expect(validateMessage(frame)).toEqual({valid: true, data: frame});
  }
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({
      valid: false,
      error: expect.stringMatching(/limit/i),
    });
  }
  for (const cursor of ['not a date', before.updatedAt, null, {}, {updatedAt: before.updatedAt}, {sessionId: 'x'},
    {updatedAt: 'not a date', sessionId: 'x'}, {updatedAt: 123, sessionId: 'x'}, {...before, sessionId: 42}]) {
    expect(validateMessage({type: 'list_conversations', before: cursor})).toEqual({
      valid: false,
      error: expect.stringMatching(/before/i),
    });
  }
  const incoming: IncomingMessage[] = [{type: 'user_message', content: 'hello'}, {type: 'ping', timestamp: 1}];
  for (const frame of incoming) expect(validateMessage(frame)).toEqual({valid: true, data: frame});
  const outgoing: OutgoingMessage[] = [
    {type: 'connected', sessionId: 's', message: 'hello', examplePrompts: []},
    {type: 'connected', sessionId: 's', message: 'hello', examplePrompts: [], resumed: true, entryCount: 0},
    {type: 'connected', sessionId: 's', message: 'hello', examplePrompts: [], resumed: false, resumeFailure: 'unknown'},
    {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'hello', timestamp: before.updatedAt}},
    {type: 'entry_delta', index: 0, delta: 'hello'}, {type: 'entry_commit', index: 0},
    {type: 'entry_skip', index: 0}, {type: 'error', code: 'SERVER_ERROR', message: 'failed'},
    {type: 'pong', timestamp: 1}, {type: 'stream_end'},
  ];
  expect(JSON.parse(JSON.stringify(outgoing))).toEqual(outgoing);
});

// spec: specs/hal-engine-conversation-list/spec.md#websocket-history
it('lists only the authenticated owner with wire dates, pages ties, and resumes a listed conversation', async () => {
  const store = new ObservedStore();
  const stamp = new Date(Date.now() + 60_000).toISOString();
  for (const id of ['a', 'b']) {
    store.create(id, 'owner', {authHeaders: {Authorization: 'private-credential'}}).entries.push({
      role: 'user', content: "'`private-content-${id}`, timestamp: stamp,
    });
  }
  store.create('"'foreign', 'another-user');
  const base = await start(store, {enabled: true});
  const peer = await connect(base);
  expect(peer.frames.map(frame => frame.type)).toEqual(['connected']);
  const expected = JSON.parse(JSON.stringify(InMemorySessionStore.prototype.listFor.call(store, 'owner'))) as Row[];
  expect(expected).toHaveLength(3);
  expect(await request(peer, {type: 'list_conversations', userId: 'another-user'})).toEqual([
    {type: 'conversation_list', conversations: expected},
  ]);
  expect(store.requests).toEqual([['owner', {limit: undefined, before: undefined}]]);
  expect(expected.map(row => row.sessionId)).toEqual(['b', 'a', peer.frames[0].sessionId]);
  for (const row of expected) {
    expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  const page: Row[] = [];
  let before: {updatedAt: string; sessionId: string} | undefined;
  for (const row of expected) {
    expect(await request(peer, {type: 'list_conversations', limit: 1, before})).toEqual([
      {type: 'conversation_list', conversations: [row]},
    ]);
    expect(store.requests.at(-1)).toEqual(['owner', {limit: 1, before}]);
    page.push(row);
    before = {updatedAt: row.updatedAt, sessionId: row.sessionId};
  }
  expect(await request(peer, {type: 'list_conversations', limit: 1, before})).toEqual([
    {type: 'conversation_list', conversations: []},
  ]);
  const resumed = await connect("'`${base}?sessionId=${page[0].sessionId}`);
  resumed.socket.send(JSON.stringify({type: '"'ping', timestamp: 1}));
  await waitFor(() => resumed.frames.some(frame => frame.type === 'pong'));
  expect(resumed.frames[0]).toMatchObject({type: 'connected', resumed: true, entryCount: 1, sessionId: 'b'});
  expect(resumed.frames.slice(1)).toEqual([
    {type: 'entry_upsert', index: 0, entry: store.get('b')"'!.entries[0]}, {type: '"'pong', timestamp: 1},
  ]);
});

// spec: specs/hal-engine-conversation-list/spec.md#history-opt-in
it('refuses unavailable history with UNSUPPORTED and warns when history cannot be resumed', async () => {
  const store = new ObservedStore();
  for (const history of [undefined, {enabled: false}]) {
    const peer = await connect(await start(store, history));
    expect(await request(peer, {type: 'list_conversations'})).toEqual([
      {type: 'error', code: 'UNSUPPORTED', message: expect.any(String)},
    ]);
  }
  expect(store.requests).toEqual([]);
  const peer = await connect(await start(originalMembers(store), {enabled: true}));
  expect(await request(peer, {type: 'list_conversations'})).toEqual([
    {type: 'error', code: 'UNSUPPORTED', message: expect.any(String)},
  ]);
  await start(store, {enabled: true}, false);
  expect(logs.some(line => line.level === 'warn' && /history/i.test(line.message) && /resume/i.test(line.message))).toBe(true);
});

// spec: specs/hal-engine-conversation-list/spec.md#history-failures
it('distinguishes a real store failure from a collection unable to list without leaking details or closing the socket', async () => {
  const client = new MongoClient('mongodb://127.0.0.1:1/private-history');
  const collection = client.db().collection<MongoSessionDocument>('private-conversations');
  await client.close();
  const cannotList = new MongoSessionStore({collection: {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  }});
  const failed = new MongoSessionStore({collection});
  for (const [listing, code] of [[failed, 'SERVER_ERROR'], [cannotList, 'UNSUPPORTED']] as const) {
    const store = {...originalMembers(new InMemorySessionStore()), listFor: listing.listFor.bind(listing)};
    const peer = await connect(await start(store, {enabled: true}));
    const result = await request(peer, {type: 'list_conversations', userId: 'private-user-content'});
    expect(result).toEqual([{type: 'error', code, message: expect.any(String)}]);
    expect(JSON.stringify(result)).not.toMatch(/Mongo|connect|find|private-|127\\.0\\.0\\.1/i);
    expect(peer.socket.readyState).toBe(WebSocket.OPEN);
    const failures = logs.filter(line => ['warn', 'error'].includes(line.level) && line.fields?.sessionId === peer.frames[0].sessionId);
    expect(failures.length).toBeGreaterThan(0);
    expect(JSON.stringify(failures)).not.toMatch(/private-user-content|credential-not-for-history/);
  }
});

// spec: specs/hal-engine-conversation-list/spec.md#history-during-turn
it('answers history before the pending turn releases its session lock', async () => {
  let release"'!: () => void;
  const gate = new Promise<void>(resolve => { release = resolve; });
  let entered = false;
  const peer = await connect(await start(new InMemorySessionStore(), {enabled: true}, true, {
    beforeModelResponse: async (_session, prompt) => { entered = true; await gate; return prompt; },
  }));
  try {
    peer.socket.send(JSON.stringify({type: '"'user_message', content: 'private pending turn'}));
    await waitFor(() => entered);
    const result = await request(peer, {type: 'list_conversations'});
    expect(result).toEqual([{type: 'conversation_list', conversations: [{
      sessionId: peer.frames[0].sessionId, createdAt: expect.any(String), updatedAt: expect.any(String), entryCount: 1,
    }]}]);
    expect(peer.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    peer.socket.close();
    await once(peer.socket, 'close');
    // The close aborts the real turn before the provider can make a network request.
    release();
  }
});
